@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&family=JetBrains+Mono:wght@400;500;600;700&display=swap');

:root {
  /* Core surfaces */
  --bg: #090b10;
  --bg-surface: #0e121b;
  --surface: #121824;
  --surface-2: #182030;
  --surface-subtle: #0f1420;
  --surface-card: #141b2a;

  /* Borders */
  --border: rgba(255, 255, 255, 0.08);
  --border-dark: rgba(255, 255, 255, 0.14);
  --border-subtle: rgba(255, 255, 255, 0.05);
  --border-hover: rgba(255, 255, 255, 0.22);
  --border-accent: rgba(245, 158, 11, 0.35);

  /* Text */
  --text: #f8fafc;
  --text-secondary: #cbd5e1;
  --text-muted: #8492a6;
  --text-dimmer: #475569;
  --text-sub: #64748b;

  /* Accent */
  --accent: #f59e0b;
  --accent-fg: #000000;
  --accent-hover: #fbbf24;
  --accent-soft: rgba(245, 158, 11, 0.12);
  --accent-border: rgba(245, 158, 11, 0.28);
  --accent-text: #f59e0b;

  /* Semantic status colors */
  --emerald: #10b981;
  --emerald-soft: rgba(16, 185, 129, 0.12);
  --emerald-border: rgba(16, 185, 129, 0.25);
  --indigo: #6366f1;
  --indigo-soft: rgba(99, 102, 241, 0.12);
  --indigo-border: rgba(99, 102, 241, 0.25);
  --rose: #f43f5e;
  --rose-soft: rgba(244, 63, 94, 0.12);
  --rose-border: rgba(244, 63, 94, 0.25);

  /* Radii */
  --radius: 8px;
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 14px;
  --radius-xl: 20px;

  /* Shadows */
  --shadow-xs: 0 1px 2px rgba(0, 0, 0, 0.3);
  --shadow-sm: 0 2px 4px rgba(0, 0, 0, 0.4);
  --shadow-md: 0 6px 18px -2px rgba(0, 0, 0, 0.5);
  --shadow-lg: 0 14px 30px -4px rgba(0, 0, 0, 0.6);

  /* Typography */
  --font: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --mono: "JetBrains Mono", ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  font-size: 15px;
  line-height: 1.6;
  letter-spacing: -0.011em;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}

code, pre, .mono {
  font-family: var(--mono);
}

/* Container */
.container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}

/* Pulse animation for live dots */
@keyframes pulse-dot {
  0% { box-shadow: 0 0 0 0 rgba(16, 185, 129, 0.4); }
  70% { box-shadow: 0 0 0 6px rgba(16, 185, 129, 0); }
  100% { box-shadow: 0 0 0 0 rgba(16, 185, 129, 0); }
}

.pulse-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #10b981;
  box-shadow: 0 0 0 2px rgba(16, 185, 129, 0.2);
  animation: pulse-dot 2s infinite;
  flex-shrink: 0;
  display: inline-block;
}

.live-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #10b981;
  box-shadow: 0 0 0 2px rgba(16, 185, 129, 0.2);
  animation: pulse-dot 2s infinite;
  flex-shrink: 0;
  display: inline-block;
}

/* Eyebrow badge */
.eyebrow-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 14px;
  border-radius: 100px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid var(--border);
  font-size: 12.5px;
  font-weight: 600;
  color: var(--text-secondary);
  margin-bottom: 24px;
  backdrop-filter: blur(8px);
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font-family: var(--font);
  font-size: 13.5px;
  font-weight: 600;
  padding: 10px 20px;
  border-radius: var(--radius-md);
  text-decoration: none;
  cursor: pointer;
  transition: all 0.15s cubic-bezier(0.16, 1, 0.3, 1);
  border: 1px solid transparent;
  white-space: nowrap;
}

.btn:active {
  transform: translateY(1px) scale(0.98);
}

.btn-lg {
  padding: 13px 26px;
  font-size: 15px;
  border-radius: var(--radius-lg);
}

.btn-primary {
  background: linear-gradient(135deg, #f59e0b 0%, #d97706 100%);
  color: #000000;
  border-color: #f59e0b;
  font-weight: 700;
  box-shadow: 0 2px 10px rgba(245, 158, 11, 0.3), inset 0 1px 0 rgba(255, 255, 255, 0.3);
}

.btn-primary:hover {
  background: linear-gradient(135deg, #fbbf24 0%, #f59e0b 100%);
  box-shadow: 0 4px 16px rgba(245, 158, 11, 0.4);
}

.btn-outline {
  background: var(--surface);
  color: var(--text-secondary);
  border-color: var(--border);
  box-shadow: var(--shadow-xs);
}

.btn-outline:hover {
  background: var(--surface-2);
  border-color: var(--border-hover);
  color: var(--text);
}

/* Hero Preview Component */
.hero-preview {
  margin: 0 auto;
  max-width: 1060px;
  border-radius: var(--radius-xl);
  border: 1px solid var(--border-dark);
  background: var(--surface-card);
  box-shadow: var(--shadow-lg);
  overflow: hidden;
  text-align: left;
}

.preview-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 22px;
  background: rgba(14, 18, 27, 0.95);
  border-bottom: 1px solid var(--border);
  font-size: 12.5px;
}

.preview-tenant {
  display: flex;
  align-items: center;
  gap: 10px;
  font-weight: 600;
  color: var(--text);
}

.preview-body {
  display: grid;
  grid-template-columns: 1fr 1fr;
  min-height: 380px;
}

@media (max-width: 860px) {
  .preview-body {
    grid-template-columns: 1fr;
  }
}

.preview-pane {
  padding: 24px;
  border-right: 1px solid var(--border);
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.preview-pane:last-child {
  border-right: none;
}

.preview-label {
  font-size: 11.5px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--text-muted);
}

.preview-bubble {
  padding: 14px 16px;
  border-radius: var(--radius-md);
  font-size: 13.5px;
  line-height: 1.55;
  border: 1px solid var(--border);
}

.preview-bubble.caller {
  background: rgba(255, 255, 255, 0.03);
  color: var(--text-secondary);
}

.preview-bubble.agent {
  background: rgba(245, 158, 11, 0.06);
  border-color: rgba(245, 158, 11, 0.22);
  color: var(--text);
}

.preview-tool-card {
  padding: 14px;
  border-radius: var(--radius-md);
  background: #090c12;
  border: 1px solid var(--border);
  font-family: var(--mono);
  font-size: 12px;
}

.tool-tag {
  display: inline-block;
  padding: 2px 7px;
  border-radius: 4px;
  font-size: 11px;
  font-weight: 600;
  background: rgba(99, 102, 241, 0.15);
  color: #a5b4fc;
  border: 1px solid rgba(99, 102, 241, 0.3);
}

/* Metric card */
.metric-card {
  padding: 22px;
  border-radius: var(--radius-lg);
  background: var(--surface-card);
  border: 1px solid var(--border);
  transition: border-color 0.15s ease;
}

.metric-card:hover {
  border-color: var(--border-hover);
}

.metric-val {
  font-size: 32px;
  font-weight: 800;
  line-height: 1.1;
  color: var(--text);
  margin-top: 6px;
}

.metric-sub {
  font-size: 12.5px;
  color: var(--text-muted);
  margin-top: 4px;
}

/* Custom Scrollbars */
::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}
::-webkit-scrollbar-track {
  background: transparent;
}
::-webkit-scrollbar-thumb {
  background-color: #27272a;
  border-radius: 3px;
}

