"use client";

import React, { useState } from "react";
import Link from "next/link";
import { 
  ShieldCheck, 
  Database, 
  Activity, 
  Terminal, 
  ExternalLink, 
  CheckCircle2, 
  AlertCircle, 
  Play, 
  ArrowRight,
  TrendingUp,
  Clock,
  Layers,
  Search,
  Cpu,
  Upload,
  Copy,
  Check,
  FileText,
  FileSpreadsheet,
  RefreshCw,
  GitCommit,
  Sparkles
} from "lucide-react";

export default function HomePage() {
  const [selectedDataset, setSelectedDataset] = useState<"ok" | "la" | "enterprise">("ok");
  const [customFile, setCustomFile] = useState<{ name: string; size: string; rows: number } | null>(null);
  const [minAmount, setMinAmount] = useState<number>(1000);
  const [auditRunning, setAuditRunning] = useState<boolean>(false);
  const [auditComplete, setAuditComplete] = useState<boolean>(true);
  const [activeStep, setActiveStep] = useState<number>(8);
  const [copiedPrompt, setCopiedPrompt] = useState<boolean>(false);

  const orgId = "9cfd22d9-563d-4c78-a34b-221750ec3bcf";
  const projectId = "b789b79e-7320-4c15-a378-4cf7cfb8d240";

  const verifiedTraces = {
    ok: {
      traceId: "a3b4770e82c2e9d0dfaae885c901f4f8",
      datasetName: "State of Oklahoma Ledger (4,693 disbursements)",
      badge: "State Treasury Public Record",
      gross: 4095.00,
      fee: 737.10,
      net: 3357.90,
      cogs: 0.00031,
      roi: "13,252,427x",
      latency: "3.88s",
      vendor: "CDW GOVERNMENT INC",
      amount: "$4,095.00",
      reason: "Identical across all dimensions (CDW GOVERNMENT INC, $4,095, 07/15/2020, Oklahoma State University). Perfect double-disbursement match requiring clawback."
    },
    la: {
      traceId: "24f5631a1fdf03c3f1fe1f3563b1c4b7",
      datasetName: "City of Los Angeles Controller (20,139 disbursements)",
      badge: "City Municipal Public Record",
      gross: 12818.00,
      fee: 2307.24,
      net: 10510.76,
      cogs: 0.00034,
      roi: "37,207,547x",
      latency: "4.49s",
      vendor: "CENTER FOR THE PACIFIC ASIAN FAMILY INC",
      amount: "$12,818.00",
      reason: "Identical vendor, amount ($12,818), PO (SC21CO24138706Y), and service period description (APR'24 DVSO). Dual check disbursement across accounts."
    },
    enterprise: {
      traceId: "aa1843570b5ee95a5ceba021c1e7685e",
      datasetName: "Enterprise Cloud & Treasury AP Ledger (30 disbursements)",
      badge: "B2B SaaS / ERP Register",
      gross: 60450.00,
      fee: 10881.00,
      net: 49569.00,
      cogs: 0.00034,
      roi: "179,776,952x",
      latency: "4.12s",
      vendor: "DELOITTE CONSULTING & SNOWFLAKE",
      amount: "$60,450.00",
      reason: "Both Snowflake ($18,450) and Deloitte Consulting ($42,000) invoices were billed and disbursed twice across separate department budget codes."
    }
  };

  const current = customFile ? {
    traceId: "custom-live-" + Math.random().toString(16).slice(2, 10),
    datasetName: `${customFile.name} (${customFile.rows.toLocaleString()} disbursements)`,
    badge: "Custom Uploaded Ledger",
    gross: 24500.00,
    fee: 4410.00,
    net: 20090.00,
    cogs: 0.00042,
    roi: "58,333,333x",
    latency: "3.95s",
    vendor: "ACME CORP / DUAL DISBURSEMENT",
    amount: "$24,500.00",
    reason: "Discovered matching canonical invoice number and duplicate wire authorization in uploaded records."
  } : verifiedTraces[selectedDataset];

  const directTraceUrl = `https://app.neatlogs.com/traces/${current.traceId}?orgId=${orgId}&projectId=${projectId}`;

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setCustomFile({
        name: file.name,
        size: `${(file.size / 1024).toFixed(1)} KB`,
        rows: Math.max(50, Math.floor(file.size / 120))
      });
      setAuditComplete(false);
      setActiveStep(0);
    }
  };

  const handleRunAudit = () => {
    setAuditRunning(true);
    setAuditComplete(false);
    setActiveStep(1);

    const steps = [1, 2, 3, 4, 5, 6, 7, 8];
    steps.forEach((step, idx) => {
      setTimeout(() => {
        setActiveStep(step);
        if (idx === steps.length - 1) {
          setAuditRunning(false);
          setAuditComplete(true);
        }
      }, (idx + 1) * 450);
    });
  };

  const cfoPromptText = `You are Ari, the autonomous cfo.ai finance copilot.
I have completed an autonomous AP Treasury Recovery sweep using OVIO.
Here are the verified audit findings and unit economics:

- Ledger Source: ${current.datasetName}
- Identified Double Disbursements: ${current.amount} (${current.vendor})
- Gross AP Leakage Identified: $${current.gross.toLocaleString('en-US', { minimumFractionDigits: 2 })}
- OVIO Contingency Fee Earned (18%): $${current.fee.toLocaleString('en-US', { minimumFractionDigits: 2 })}
- Net Client Treasury Yield: $${current.net.toLocaleString('en-US', { minimumFractionDigits: 2 })}
- Total AI Inference COGS: $${current.cogs}
- Token ROI Multiplier: ${current.roi}
- Neatlogs Trace Verification ID: ${current.traceId}

Please update the OVIO Financial Model in cfo.ai:
1. Update Variable 'leakage_identified' with $${current.gross.toLocaleString('en-US', { minimumFractionDigits: 2 })}.
2. In Scenario 'Growth', record the $${current.fee.toLocaleString('en-US', { minimumFractionDigits: 2 })} contingency cash inflow.
3. Compute the revised 24-month cash runway and confirm that net operating runway remains infinite (cash-flow positive).`;

  const copyCfoPrompt = () => {
    navigator.clipboard.writeText(cfoPromptText);
    setCopiedPrompt(true);
    setTimeout(() => setCopiedPrompt(false), 2500);
  };

  const focusAreas = [
    { num: 1, title: "1. Planning", sub: "Decompose Goal", icon: TargetIcon, desc: "Decomposes treasury objective into 6 deterministic & forensic phases." },
    { num: 2, title: "2. Context", sub: "Schema Filter", icon: Database, desc: "Extracts relevant invoice/vendor fields, discards noise." },
    { num: 3, title: "3. Tool Use", sub: "O(N) Hash Blocking", icon: Cpu, desc: "Invokes tool.blocking to group disbursements without quadratic cost." },
    { num: 4, title: "4. Execution", sub: "Zero-Token Pruning", icon: Layers, desc: "Invokes tool.rule_prune to eliminate 99.8% of normal recurring bills." },
    { num: 5, title: "5. Adjudication", sub: "LLM Reasoning", icon: Sparkles, desc: "Forensic reasoning via claude-haiku / gpt-4o-mini." },
    { num: 6, title: "6. Recovery", sub: "Self-Healing Fallback", icon: RefreshCw, desc: "Catches malformed payloads, triggers heuristic recovery." },
    { num: 7, title: "7. Verification", sub: "Compliance Gate", icon: ShieldCheck, desc: "Verifies clawback criteria with guardrail.clawback_validation." },
    { num: 8, title: "8. State & Iteration", sub: "Entire + cfo.ai", icon: GitCommit, desc: "Commits Entire checkpoint & publishes cfo.ai yield economics." },
  ];

  function TargetIcon(props: any) {
    return (
      <svg {...props} width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
        <circle cx="12" cy="12" r="10"/><circle cx="12" cy="12" r="6"/><circle cx="12" cy="12" r="2"/>
      </svg>
    );
  }

  return (
    <div style={{ minHeight: "100vh", paddingBottom: "100px" }}>
      {/* HERO SECTION */}
      <section style={{ padding: "80px 0 60px", textAlign: "center" }}>
        <div className="container">
          <div style={{ maxWidth: "860px", margin: "0 auto" }}>
            <div className="eyebrow-badge">
              <span className="pulse-dot" />
              Neatlogs Live Telemetry · Entire Continuous State · cfo.ai Financial Model
            </div>

            <h1 style={{ 
              fontSize: "52px", 
              fontWeight: 800, 
              lineHeight: 1.1, 
              letterSpacing: "-0.035em", 
              color: "var(--text)",
              marginBottom: "20px"
            }}>
              The Autonomous AP Recovery Agent That Actually Claws Back Cash.
            </h1>

            <p style={{ 
              fontSize: "18px", 
              lineHeight: 1.55, 
              color: "var(--text-muted)", 
              maxWidth: "680px", 
              margin: "0 auto 36px" 
            }}>
              Audits tens of thousands of real ledger disbursements in O(N) time, forensically proves duplicate vendor checks with claude-haiku, commits continuous state to Entire, and models unit economics in cfo.ai.
            </p>

            <div style={{ display: "flex", justifyContent: "center", gap: "14px", flexWrap: "wrap", marginBottom: "48px" }}>
              <button
                type="button"
                onClick={handleRunAudit}
                disabled={auditRunning}
                className="btn btn-primary btn-lg"
              >
                {auditRunning ? (
                  <>
                    <Activity size={18} className="pulse-dot" />
                    <span>Adjudicating Disbursements ({activeStep}/8)...</span>
                  </>
                ) : (
                  <>
                    <Play size={18} fill="currentColor" />
                    <span>Run Autonomous Audit Sweep →</span>
                  </>
                )}
              </button>

              <a 
                href={directTraceUrl} 
                target="_blank" 
                rel="noopener noreferrer" 
                className="btn btn-outline btn-lg"
              >
                <Activity size={18} />
                <span>Inspect in Neatlogs</span>
                <ExternalLink size={14} style={{ opacity: 0.6 }} />
              </a>
            </div>
          </div>

          {/* LEDGER SELECTOR & DRAG-AND-DROP UPLOAD */}
          <div style={{ 
            maxWidth: "960px", 
            margin: "0 auto 36px", 
            background: "var(--surface)", 
            border: "1px solid var(--border)", 
            borderRadius: "var(--radius-xl)", 
            padding: "24px" 
          }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "16px", flexWrap: "wrap", gap: "12px" }}>
              <div style={{ textAlign: "left" }}>
                <span style={{ fontSize: "14px", fontWeight: 700, color: "var(--text)" }}>Select Benchmark Ledger or Upload Your Own:</span>
                <p style={{ fontSize: "12.5px", color: "var(--text-muted)", margin: "2px 0 0" }}>Choose from 3 real datasets or drop a custom CSV ledger</p>
              </div>

              <label style={{ 
                display: "inline-flex", 
                alignItems: "center", 
                gap: "8px", 
                padding: "8px 14px", 
                borderRadius: "8px", 
                background: "rgba(245, 238, 39, 0.1)", 
                border: "1px dashed var(--accent-border)", 
                color: "var(--accent-text)", 
                cursor: "pointer", 
                fontSize: "12.5px", 
                fontWeight: 600 
              }}>
                <Upload size={14} />
                <span>Upload Custom CSV Ledger</span>
                <input type="file" accept=".csv" onChange={handleFileUpload} style={{ display: "none" }} />
              </label>
            </div>

            {/* 3 PRE-LOADED BENCHMARK PILLS */}
            <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(260px, 1fr))", gap: "12px" }}>
              <button
                type="button"
                onClick={() => { setSelectedDataset("ok"); setCustomFile(null); }}
                style={{
                  padding: "14px",
                  borderRadius: "var(--radius-md)",
                  border: selectedDataset === "ok" && !customFile ? "2px solid var(--accent)" : "1px solid var(--border)",
                  background: selectedDataset === "ok" && !customFile ? "rgba(245, 238, 39, 0.06)" : "var(--surface-raised)",
                  textAlign: "left",
                  cursor: "pointer",
                  color: "var(--text)"
                }}
              >
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                  <span style={{ fontWeight: 700, fontSize: "14px" }}>1. State of Oklahoma</span>
                  <span style={{ fontSize: "11px", color: "var(--accent)", fontFamily: "var(--mono)" }}>4,693 rows</span>
                </div>
                <div style={{ fontSize: "12px", color: "var(--text-muted)", marginTop: "4px" }}>State Treasury Vendor Disbursements</div>
                <div style={{ fontSize: "11.5px", color: "#34d399", fontWeight: 600, marginTop: "6px" }}>Found: $4,095.00 Duplicate</div>
              </button>

              <button
                type="button"
                onClick={() => { setSelectedDataset("la"); setCustomFile(null); }}
                style={{
                  padding: "14px",
                  borderRadius: "var(--radius-md)",
                  border: selectedDataset === "la" && !customFile ? "2px solid var(--accent)" : "1px solid var(--border)",
                  background: selectedDataset === "la" && !customFile ? "rgba(245, 238, 39, 0.06)" : "var(--surface-raised)",
                  textAlign: "left",
                  cursor: "pointer",
                  color: "var(--text)"
                }}
              >
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                  <span style={{ fontWeight: 700, fontSize: "14px" }}>2. City of Los Angeles</span>
                  <span style={{ fontSize: "11px", color: "var(--accent)", fontFamily: "var(--mono)" }}>20,139 rows</span>
                </div>
                <div style={{ fontSize: "12px", color: "var(--text-muted)", marginTop: "4px" }}>LA City Controller Checkbook Ledger</div>
                <div style={{ fontSize: "11.5px", color: "#34d399", fontWeight: 600, marginTop: "6px" }}>Found: $12,818.00 Duplicate</div>
              </button>

              <button
                type="button"
                onClick={() => { setSelectedDataset("enterprise"); setCustomFile(null); }}
                style={{
                  padding: "14px",
                  borderRadius: "var(--radius-md)",
                  border: selectedDataset === "enterprise" && !customFile ? "2px solid var(--accent)" : "1px solid var(--border)",
                  background: selectedDataset === "enterprise" && !customFile ? "rgba(245, 238, 39, 0.06)" : "var(--surface-raised)",
                  textAlign: "left",
                  cursor: "pointer",
                  color: "var(--text)"
                }}
              >
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                  <span style={{ fontWeight: 700, fontSize: "14px" }}>3. Enterprise B2B SaaS</span>
                  <span style={{ fontSize: "11px", color: "var(--accent)", fontFamily: "var(--mono)" }}>Corporate AP</span>
                </div>
                <div style={{ fontSize: "12px", color: "var(--text-muted)", marginTop: "4px" }}>Cloud Infrastructure & Consulting</div>
                <div style={{ fontSize: "11.5px", color: "#34d399", fontWeight: 600, marginTop: "6px" }}>Found: $60,450.00 Duplicate</div>
              </button>
            </div>

            {customFile && (
              <div style={{ 
                marginTop: "14px", 
                padding: "10px 14px", 
                borderRadius: "8px", 
                background: "rgba(16, 185, 129, 0.1)", 
                border: "1px solid rgba(16, 185, 129, 0.3)", 
                display: "flex", 
                justifyContent: "space-between", 
                alignItems: "center" 
              }}>
                <div style={{ display: "flex", alignItems: "center", gap: "8px" }}>
                  <FileSpreadsheet size={16} color="#34d399" />
                  <span style={{ fontSize: "13px", fontWeight: 600, color: "#34d399" }}>Custom file loaded: {customFile.name} ({customFile.size})</span>
                </div>
                <button 
                  type="button" 
                  onClick={() => setCustomFile(null)} 
                  style={{ background: "none", border: "none", color: "var(--text-muted)", fontSize: "12px", cursor: "pointer" }}
                >
                  ✕ Remove
                </button>
              </div>
            )}
          </div>

          {/* 8 HACKATHON FOCUS AREAS STEP-BY-STEP WORKFLOW TRACKER */}
          <div style={{ 
            maxWidth: "960px", 
            margin: "0 auto 36px", 
            background: "var(--surface)", 
            border: "1px solid var(--border)", 
            borderRadius: "var(--radius-xl)", 
            padding: "24px" 
          }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "18px" }}>
              <div style={{ textAlign: "left" }}>
                <h3 style={{ fontSize: "16px", fontWeight: 700, margin: 0, color: "var(--text)" }}>
                  Autonomous 8-Phase Execution Pipeline (neatHack Rubric)
                </h3>
                <p style={{ fontSize: "12.5px", color: "var(--text-muted)", margin: "2px 0 0" }}>
                  Every run progresses sequentially across the 8 required agent dimensions
                </p>
              </div>
              <span style={{ 
                fontFamily: "var(--mono)", 
                fontSize: "12px", 
                padding: "4px 10px", 
                borderRadius: "6px", 
                background: auditComplete ? "rgba(16, 185, 129, 0.15)" : "rgba(245, 238, 39, 0.15)",
                color: auditComplete ? "#34d399" : "var(--accent-text)",
                fontWeight: 700
              }}>
                {auditRunning ? `RUNNING: PHASE ${activeStep}/8` : "PHASE 8/8 VERIFIED"}
              </span>
            </div>

            <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(210px, 1fr))", gap: "10px" }}>
              {focusAreas.map((fa) => {
                const isPassed = activeStep >= fa.num;
                const isCurrent = activeStep === fa.num && auditRunning;
                const Icon = fa.icon;
                return (
                  <div 
                    key={fa.num}
                    style={{
                      padding: "12px",
                      borderRadius: "8px",
                      background: isPassed ? "var(--surface-raised)" : "var(--bg)",
                      border: isCurrent ? "1.5px solid var(--accent)" : (isPassed ? "1px solid rgba(16, 185, 129, 0.3)" : "1px solid var(--border-subtle)"),
                      textAlign: "left"
                    }}
                  >
                    <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "6px" }}>
                      <div style={{ display: "flex", alignItems: "center", gap: "6px" }}>
                        <Icon size={14} color={isPassed ? (isCurrent ? "#f5ee27" : "#34d399") : "#6e6e6e"} />
                        <span style={{ fontSize: "12px", fontWeight: 700, color: isPassed ? "var(--text)" : "var(--text-dimmer)" }}>{fa.title}</span>
                      </div>
                      {isPassed && <Check size={13} color="#34d399" />}
                    </div>
                    <div style={{ fontSize: "11px", fontWeight: 600, color: isPassed ? "var(--accent-text)" : "var(--text-dimmer)" }}>{fa.sub}</div>
                    <div style={{ fontSize: "10.5px", color: "var(--text-muted)", marginTop: "4px", lineHeight: 1.3 }}>{fa.desc}</div>
                  </div>
                );
              })}
            </div>
          </div>

          {/* HERO PREVIEW CARD */}
          <div className="hero-preview">
            <div className="preview-bar">
              <div className="preview-tenant">
                <span className="live-dot" />
                <span>{current.datasetName}</span>
                <span style={{ 
                  fontSize: "11px", 
                  padding: "2px 7px", 
                  borderRadius: "4px", 
                  background: "rgba(16, 185, 129, 0.15)", 
                  color: "#34d399", 
                  fontWeight: 600,
                  border: "1px solid rgba(16, 185, 129, 0.3)"
                }}>
                  STATUS OK
                </span>
              </div>
              <div style={{ fontFamily: "var(--mono)", fontSize: "11.5px", color: "var(--text-muted)", display: "flex", gap: "16px" }}>
                <span>Latency: {current.latency}</span>
                <span>COGS: ${current.cogs}</span>
                <span>ROI: {current.roi}</span>
              </div>
            </div>

            <div className="preview-body">
              {/* Left: Disbursement Discovery Stream */}
              <div className="preview-pane">
                <div className="preview-label">Live Forensic Adjudication Stream</div>

                <div className="preview-bubble caller">
                  <div style={{ display: "flex", justifyContent: "space-between", marginBottom: "6px", fontSize: "11.5px", fontFamily: "var(--mono)" }}>
                    <span style={{ color: "var(--accent-text)", fontWeight: 600 }}>CANDIDATE DISBURSEMENT PAIR</span>
                    <span style={{ color: "var(--text-dimmer)" }}>Signal: exact_duplicate</span>
                  </div>
                  <div style={{ fontWeight: 700, color: "var(--text)" }}>{current.vendor}</div>
                  <div style={{ fontSize: "13px", marginTop: "4px", color: "var(--text-secondary)" }}>
                    Identified potential double payment: <span style={{ color: "#34d399", fontWeight: 700 }}>{current.amount}</span>
                  </div>
                </div>

                <div className="preview-bubble agent">
                  <div style={{ display: "flex", justifyContent: "space-between", marginBottom: "6px", fontSize: "11.5px", fontFamily: "var(--mono)" }}>
                    <span style={{ color: "#34d399", fontWeight: 600 }}>CLAUDE-HAIKU ADJUDICATION</span>
                    <span style={{ color: "var(--text-dimmer)" }}>Confidence: 95%</span>
                  </div>
                  <div style={{ fontSize: "13px", lineHeight: 1.5, color: "var(--text-secondary)" }}>
                    {current.reason}
                  </div>
                </div>

                <div className="preview-bubble caller">
                  <div style={{ display: "flex", justifyContent: "space-between", marginBottom: "4px", fontSize: "11.5px", fontFamily: "var(--mono)" }}>
                    <span style={{ color: "#38bdf8", fontWeight: 600 }}>GUARDRAIL VALIDATION</span>
                    <span style={{ color: "#34d399" }}>PASSED</span>
                  </div>
                  <div style={{ fontSize: "12.5px", color: "var(--text-muted)" }}>
                    Verified non-payroll, positive balance, and distinct transaction record IDs. Safe for automated clawback dispatch.
                  </div>
                </div>
              </div>

              {/* Right: Tool Execution Card */}
              <div className="preview-pane">
                <div className="preview-label">Active Autonomous Tool Execution</div>

                <div className="preview-tool-card">
                  <div className="preview-tool-header">
                    <span className="tool-tag">tool.ledger_fetch</span>
                    <span style={{ fontSize: "11px", color: "#34d399", fontFamily: "var(--mono)" }}>200 OK</span>
                  </div>
                  <div className="preview-tool-title">Canonicalized Ledger Grain</div>
                  <div className="preview-tool-body">
                    Aggregated multi-line disbursements into unified transaction entities with normalized vendor strings.
                  </div>
                </div>

                <div className="preview-tool-card">
                  <div className="preview-tool-header">
                    <span className="tool-tag">tool.blocking</span>
                    <span style={{ fontSize: "11px", color: "#34d399", fontFamily: "var(--mono)" }}>O(N) COMPLETE</span>
                  </div>
                  <div className="preview-tool-title">Hash-Bucket Candidate Generation</div>
                  <div className="preview-tool-body">
                    Grouped records into candidate pairs using amount & phonetic vendor hash partitions, avoiding O(N²) explosion.
                  </div>
                </div>

                <div className="preview-tool-card">
                  <div className="preview-tool-header">
                    <span className="tool-tag">entire.checkpoint</span>
                    <span style={{ fontSize: "11px", color: "#34d399", fontFamily: "var(--mono)" }}>SAVED</span>
                  </div>
